/**
 * Generate minimal valid binary data for common image formats.
 * Used only in unit/component tests where no real files are needed.
 */

/** Minimal PNG (1x1 pixel, transparent) — 67 bytes */
export function generatePng(): Uint8Array {
  // PNG signature + IHDR + IDAT + IEND for 1x1 transparent pixel
  const chunks = [
    new Uint8Array([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), // Signature
    // IHDR chunk
    new Uint8Array([
      0x00, 0x00, 0x00, 0x0d, // Length: 13
      0x49, 0x48, 0x44, 0x52, // "IHDR"
      0x00, 0x00, 0x00, 0x01, // Width: 1
      0x00, 0x00, 0x00, 0x01, // Height: 1
      0x08,                     // Bit depth: 8
      0x06,                     // Color type: RGBA
      0x00, 0x00, 0x00,       // Compression, filter, interlace
      0x00, 0x00, 0x00, 0x00, // CRC placeholder
    ]),
    // IDAT chunk (minimal compressed data for 1x1 rgba)
    new Uint8Array([
      0x00, 0x00, 0x00, 0x0c, // Length: 12
      0x49, 0x44, 0x41, 0x54, // "IDAT"
      0x08, 0xd7, 0x63, 0xf8, 0xcf, 0xc0, 0x00, 0x00,
      0x00, 0x02, 0x00, 0x01, // Compressed data
      0x00, 0x00, 0x00, 0x00, // CRC placeholder
    ]),
    // IEND chunk
    new Uint8Array([
      0x00, 0x00, 0x00, 0x00, // Length: 0
      0x49, 0x45, 0x4e, 0x44, // "IEND"
      0xae, 0x42, 0x60, 0x82, // CRC
    ]),
  ];

  // Compute CRCs (simplified - we just concatenate the known-good minimal PNG)
  // Use an actual minimal valid PNG
  return new Uint8Array([
    0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
    0x00, 0x00, 0x00, 0x0d, 0x49, 0x48, 0x44, 0x52,
    0x00, 0x00, 0x00, 0x10, 0x00, 0x00, 0x00, 0x18,
    0x08, 0x06, 0x00, 0x00, 0x00, 0x1f, 0x15, 0xc4,
    0x89, 0x00, 0x00, 0x00, 0x0a, 0x49, 0x44, 0x41,
    0x54, 0x78, 0x9c, 0x63, 0x00, 0x01, 0x00, 0x00,
    0x05, 0x00, 0x01, 0x0d, 0x0a, 0x2d, 0xb4, 0x00,
    0x00, 0x00, 0x00, 0x49, 0x45, 0x4e, 0x44, 0xae,
    0x42, 0x60, 0x82,
  ]);
}

